import{z as r,x as i,o as l,c as s,q as p,j as n,D as e,d as o,s as A,S as B,b as E}from"./chunks/framework.C8m1ZpeB.js";const b=JSON.parse('{"title":"MoE 微调","description":"","frontmatter":{"title":"MoE 微调","date":"2026-09-08T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/moe-finetuning.md","filePath":"llm/moe-finetuning.md","lastUpdated":1791413859000}'),d={name:"llm/moe-finetuning.md"};function m(D,a,u,f,h,L){const t=i("Mermaid");return l(),s("div",null,[a[2]||(a[2]=p('<h1 id="moe-微调" tabindex="-1">MoE 微调 <a class="header-anchor" href="#moe-微调" aria-label="Permalink to &quot;MoE 微调&quot;">​</a></h1><div class="epigraph"><p>指令微调会改写路由；只训专家不训门，或只训门不训专家，得到的是两种不同的特化漂移。</p><footer>—— 综合稀疏 MoE 在指令微调中的实践；LoRA 接到专家与门的不同槽位会改变路由还是改变专家内部</footer></div><p><a href="/llm/expert-specialization">上一课</a>在预训练分布上画专精图。下游数据更窄、更尖，门若继续学，会把大量指令打进少数专家，其余专家冻成死权重；门若冻结，新任务只能挤进旧切片。<a href="/llm/aux-loss-free-balancing">无辅助损失均衡</a> 的偏置在微调 batch 更小、更偏时也会失配。本课补微调时动哪一部分。后课剪枝假设微调已经决定哪些专家还活着。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>稠密模型微调是改一套 FFN。MoE 有三组旋钮：专家 MLP、路由门、均衡控制器（辅助权或 \\(b_i\\)）。只改专家，路由仍按预训练语义切片，新任务若落在冷门专家会欠拟合。只改门，专家内部是旧技能，门负责重分配。全开则小数据上路由先崩——辅助项或偏置来不及跟上，出现少数专家包办。缺口是按数据规模选冻结策略，而不是套稠密 LoRA 教程。</p><p><span class="marginnote">术语翻译：均衡控制器是专家维的「交通信号灯」——辅助损失或偏置 \\(b_i\\) 都属于它。\\(b_i\\) 是加在专家 \\(i\\) 得分上的可调偏置：谁最近接客太多就调低谁的加分，谁挨饿就调高，用轻量的方式把流量往均匀推。</span></p><p><span class="marginnote">LoRA 打在专家上，增加的是专家内部适应；打在 \\(W_r\\) 上，增加的是重路由。打在注意力上则与 MoE 无关。写配置时要写清槽位。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>常见配方。小数据：冻门与偏置，LoRA 所有专家或只 LoRA 预训练占用最高的子集——后者更快，但放弃冷门专家里可能有用的知识。中等数据：LoRA 专家加小学习率更新门，均衡用冻结的 \\(b\\) 或略增大容量以免 drop。大数据 / 继续预训练：全开，重新跑负载闭环。</p><p>专家并行下，微调也要 All-to-All。为省通信可把微调改成「只激活本机专家」的节点受限极端，等于把模型当多套稠密适配器，质量通常下降。另一条路是把 MoE 稠密化（所有专家变稠密 FFN 再 LoRA），通信消失、参数暴涨，只适小模型。</p><h3 id="与指令分布" tabindex="-1">与指令分布 <a class="header-anchor" href="#与指令分布" aria-label="Permalink to &quot;与指令分布&quot;">​</a></h3><p>代码指令会把路由推向代码专家。若预训练专精清晰，这是好事，应保持序列级均衡较弱，允许尖。若预训练专精本来就是词频，指令微调会进一步把功能词专家打满，需要提高容量或重训门。用上一课的干预手段在微调前后各做一次，才能看见漂移。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>门的 softmax 对小梯度很敏感：指令前缀高度相似，top-1 容易锁死。锁死后梯度只进那几个 MLP，其它专家的 LoRA 零更新，表面上「训了所有专家」实际只训热点。缓解：提高 \\(k\\)、对门加熵、或周期性把 token 强制打到占用最低的专家（与哈希混合）。这些都会伤预训练特化，是税。</p><p><span class="marginnote">直觉类比：门锁死像网红餐厅效应——评分稍有领先就吸走全部客流；其他餐厅没客人就没收入，更没法改进菜品，差距越拉越大。「提高 \\(k\\)、门加熵」相当于强制分流和给新店发代金券。</span></p><p>均衡偏置若仍按预训练步长 \\(\\gamma\\) 在微调小 batch 上更新，会剧烈振荡。微调阶段通常减小 \\(\\gamma\\) 或冻结 \\(b\\)。多任务混合微调时，不同任务想要不同热点专家，门会被拉成折中；按任务拆 LoRA 专家、共享门，往往比一个全局门伺候所有指令更稳。</p><p><span class="marginnote">数字实例：64 个专家、top-1 路由若锁死前 4 个热点，意味着约 94% 的专家权重这次微调一个梯度都没收到——LoRA 参数照样占显存，优化器却对它们零更新，「训了所有专家」只是账面说法。</span></p>',17)),(l(),n(B,null,{default:e(()=>[A(t,{id:"mermaid-49",class:"mermaid",graph:"flowchart%20TD%0A%20%20SIM%5B%22%E6%8C%87%E4%BB%A4%E5%89%8D%E7%BC%80%E9%AB%98%E5%BA%A6%E7%9B%B8%E4%BC%BC%22%5D%20--%3E%20G%5B%22%E9%97%A8%E8%BE%93%E5%87%BA%E7%9B%B8%E8%BF%91%E7%9A%84%E5%88%86%E6%95%B0%22%5D%0A%20%20G%20--%3E%20LOCK%5B%22top-1%20%E9%94%81%E6%AD%BB%E5%B0%91%E6%95%B0%E7%83%AD%E7%82%B9%E4%B8%93%E5%AE%B6%22%5D%0A%20%20LOCK%20--%3E%20GRAD%5B%22%E6%A2%AF%E5%BA%A6%E5%8F%AA%E6%B5%81%E5%85%A5%E7%83%AD%E7%82%B9%E4%B8%93%E5%AE%B6%E7%9A%84%20MLP%22%5D%0A%20%20GRAD%20--%3E%20COLD%5B%22%E5%85%B6%E4%BD%99%E4%B8%93%E5%AE%B6%20LoRA%20%E9%9B%B6%E6%9B%B4%E6%96%B0%EF%BC%8C%E6%8C%81%E7%BB%AD%E6%AC%A0%E6%8B%9F%E5%90%88%22%5D%0A%20%20COLD%20--%3E%7C%22%E4%B8%8B%E4%B8%80%E6%89%B9%E5%88%86%E6%95%B0%E5%B7%AE%E8%B7%9D%E6%9B%B4%E5%A4%A7%22%7C%20LOCK%0A%20%20LOCK%20-.-%3E%7C%22%E7%BC%93%E8%A7%A3%22%7C%20FIX%5B%22%E5%8D%87%20k%20%2F%20%E9%97%A8%E5%8A%A0%E7%86%B5%20%2F%20%E5%91%A8%E6%9C%9F%E6%80%A7%E6%89%93%E6%95%A3%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[o(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=E("p",null,[E("span",{class:"marginnote"},"任务向量算术在 MoE 上要对齐专家下标。微调若重排了路由，差值不能按层直接加。训练基础课的合并默认稠密，本课是它在稀疏上的缺口。")],-1)),a[4]||(a[4]=E("h2",{id:"边界",tabindex:"-1"},[o("边界 "),E("a",{class:"header-anchor",href:"#边界","aria-label":'Permalink to "边界"'},"​")],-1)),a[5]||(a[5]=E("p",null,"没有一种冻结策略适合所有下游。评测应报激活专家数的直方图，不只报下游分数。把 MoE 当稠密模型全参数微调，在万亿规模不可行，在百亿规模可能是最稳但最贵的路。下一课在微调后或直接在预训练检查点上剪、合并专家，以部署为目标。",-1)),(l(),n(B,null,{default:e(()=>[A(t,{id:"mermaid-59",class:"mermaid",graph:"flowchart%20TD%0A%20%20Data%5B%22%E4%B8%8B%E6%B8%B8%E6%95%B0%E6%8D%AE%E8%A7%84%E6%A8%A1%22%5D%20--%3E%20Small%5B%22%E5%86%BB%E9%97%A8%20LoRA%20%E4%B8%93%E5%AE%B6%22%5D%0A%20%20Data%20--%3E%20Mid%5B%22LoRA%20%E4%B8%93%E5%AE%B6%E5%8A%A0%E6%85%A2%E9%97%A8%22%5D%0A%20%20Data%20--%3E%20Large%5B%22%E5%85%A8%E5%BC%80%E5%8A%A0%E8%B4%9F%E8%BD%BD%E9%97%AD%E7%8E%AF%22%5D%0A%20%20Small%20--%3E%20Drift%5B%22%E7%94%A8%E5%B9%B2%E9%A2%84%E6%A3%80%E6%B5%8B%E7%89%B9%E5%8C%96%E6%BC%82%E7%A7%BB%22%5D%0A%20%20Mid%20--%3E%20Drift%0A%20%20Large%20--%3E%20Drift%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[o(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=E("h2",{id:"小结",tabindex:"-1"},[o("小结 "),E("a",{class:"header-anchor",href:"#小结","aria-label":'Permalink to "小结"'},"​")],-1)),a[7]||(a[7]=E("ul",null,[E("li",null,"MoE 微调要分别决定专家、门、均衡控制器谁动；稠密 LoRA 习惯不够。"),E("li",null,"小数据冻门防崩，风险是新任务挤旧切片；大门学习率在相似前缀上易锁死热点。"),E("li",null,"微调前后都应重测专精与占用直方图。"),E("li",null,"任务向量合并依赖专家下标稳定。"),E("li",null,"出处：稀疏 MoE 指令微调与专家/门槽位 LoRA 的工程实践。")],-1))])}const c=r(d,[["render",m]]);export{b as __pageData,c as default};
